// 自动生成：内置文章内容（构建时打包，无需 fetch）
export const builtinContents: Record<string, string> = {
  'algorithm-advanced-greedy-dp-dfs': atob(''),
  'algorithm-basics-branch-loop': atob(''),
  'csp-guide': atob(''),
  'gesp-guide': atob(''),
  'getting-started-with-react': atob(''),
  'git-essential-commands': atob(''),
  'problem-bank-luogu-nowcoder': atob(''),
  'understanding-typescript': atob(''),
};

// 运行时解码 helper
export function getBuiltinContent(slug: string): string | undefined {
  const raw = builtinContents[slug]
  if (!raw) return undefined
  // 浏览器和 Node.js 都支持 atob
  return atob(raw)
}
